/*
 * Shared by the HUD library simulator programs (test_hud.c, test_hud_draw.c, test_hud_em10ii.c), each
 * including it once: the mock register block of fw.S, a bump heap behind the malloc mock, the layer-1
 * buffers and GUI words as plain memory at the target's firmware addresses, and the dump output.
 * E-M10 II: the C side of fw_em10ii.S's mocks (widgets, GUI event post, the stock slot functions)
 * and the stock words fenykl_hud_init checks. images.c (generated by test_hud_sim.py from the stock
 * firmware) holds the image table.
 */
#ifndef _SIM_HUD_H
#define _SIM_HUD_H

#include <hud.h>

#define SIM_U8(a) (*(volatile uint8_t *)(a))
#define SIM_U16(a) (*(volatile uint16_t *)(a))
#define SIM_U32(a) (*(volatile uint32_t *)(a))

#define SIM_PITCH 896
#define SIM_GUI 0x33		/* what the "GUI" painted */

#define SIM_VRAM_TABLE FW_GPI_LAYER_VRAM
#define SIM_FONT_RES FW_GPI_FONT_RES
#define SIM_IMAGE_TABLE FW_GUI_IMAGE_TABLE
#define SIM_LAYER_BPP FW_GPI_LAYER_BPP
#define SIM_DRAW_BUF FW_GPI_DRAW_BUF
#define SIM_HIDE_MASK FW_GPI_HIDE_MASK
#define SIM_ONE_MODE FW_GPI_ONE_MODE
#define SIM_ONE_LAYER FW_GPI_ONE_LAYER
#define SIM_ONE_BUF FW_GPI_ONE_BUF
#define SIM_SUPER FW_GUI_SUPER
#define SIM_STATE FW_GUI_STATE

#define SIM_BUF0 0xA1E00000u
#define SIM_BUF1 0xA1F00000u
#define SIM_VRAM0 0x619ADF88u		/* the GUI's own place for the handles */
#define SIM_PROP_INFO (FW_PROP_TABLE + 8u * (0x8321u >> 4) + 4u)
#define SIM_INFO_BASIC 1
#define SIM_INFO_CUSTOM1 0x11
#define SIM_INFO_IMAGE 0
static volatile int8_t sim_info;	/* the INFO screen property's object */

extern const void *const sim_images[];		/* images.c: [id] -> struct gui_image */

uint32_t sim_exit_code = 99;
volatile uint32_t mreg[5];
static uint8_t sim_heap[0x100] __attribute__((aligned(4)));	/* the library takes its pool */
static unsigned int sim_heap_used;

void sim_write(const void *buf, unsigned int len);

uint32_t c_malloc(void)
{
	unsigned int size = (mreg[2] + 3) & ~3u;

	if (sim_heap_used + size > sizeof(sim_heap))
		return 0;
	sim_heap_used += size;
	return (uint32_t)&sim_heap[sim_heap_used - size];
}

uint32_t c_free(void)
{
	return 0;
}

#define SIM_WIDGETS 32
#define SIM_STOCK_MSG 0x55		/* the stock OnMessage's result */

/* A widget the factory mock made: its vtable word, then what the mocks saw. */
struct sim_widget {
	uint32_t vt;
	uint32_t parent;		/* factory and append */
	uint32_t attached;		/* parent given to the attach method */
	const uint8_t *rec;
	uint32_t handle;		/* last gui_image_set_handle */
};

static struct {
	struct sim_widget w[SIM_WIDGETS];
	uint32_t vtable[0x98 / 4];	/* +0x94: sim_attach */
	unsigned int widgets, handles, posts, flushes, stock_create, stock_destroy, stock_msg;
	uint32_t post_code;
	bool refuse_create, refuse_append, refuse_post;
} sim_gui;

extern char sim_attach[];		/* fw_em10ii.S */

uint32_t c_irq_lock(void)
{
	return 0;
}

uint32_t c_irq_unlock(void)
{
	return 0;
}

uint32_t c_dcache_flush_all(void)
{
	sim_gui.flushes++;
	return 0;
}

/* gui_widget_create(app@A0, type@D0, parent@D1, record@A1) */
uint32_t c_gui_widget_create(void)
{
	if (sim_gui.refuse_create || sim_gui.widgets == SIM_WIDGETS || mreg[2] != 0x8003)
		return 0;
	struct sim_widget *w = &sim_gui.w[sim_gui.widgets++];

	sim_gui.vtable[0x94 / 4] = (uint32_t)sim_attach;
	*w = (struct sim_widget){ .vt = (uint32_t)sim_gui.vtable, .parent = mreg[3],
				  .rec = (const uint8_t *)mreg[1] };
	return (uint32_t)w;
}

/* gui_container_append(container@A0, child@A1) */
uint32_t c_gui_container_append(void)
{
	struct sim_widget *w = (struct sim_widget *)mreg[1];

	return !sim_gui.refuse_append && w->parent == mreg[0];
}

/* gui_image_set_handle(widget@A0, handle@A1, index@D0): returns the old handle */
uint32_t c_gui_image_set_handle(void)
{
	struct sim_widget *w = (struct sim_widget *)mreg[0];
	uint32_t old = w->handle;

	if (mreg[2] == 0) {
		w->handle = mreg[1];
		sim_gui.handles++;
	}
	return old;
}

uint32_t c_gui_post(void)
{
	sim_gui.posts++;
	sim_gui.post_code = mreg[2];
	return !sim_gui.refuse_post;
}

/* widget vt+0x94 (widget@A0, parent@A1) */
uint32_t c_attach(void)
{
	((struct sim_widget *)mreg[0])->attached = mreg[1];
	return 0;
}

/* the stock functions behind the slots */
uint32_t c_panel_create(void)
{
	sim_gui.stock_create++;
	return 1;
}

uint32_t c_panel_destroy(void)
{
	sim_gui.stock_destroy++;
	return 0;
}

uint32_t c_app_message(void)
{
	sim_gui.stock_msg++;
	return SIM_STOCK_MSG;
}

/* The ISO item's record head and the stock words of the three GUI slots. */
static inline void sim_setup_widgets(void)
{
	SIM_U16(FW_GUI_INFO_ISO_RECORD) = 0x8003;
	SIM_U16(FW_GUI_INFO_ISO_RECORD + 2) = 0x91;
	SIM_U32(fenykl_slot_info_panel_create.address) = fenykl_slot_info_panel_create.expected;
	SIM_U32(fenykl_slot_info_panel_destroy.address) = fenykl_slot_info_panel_destroy.expected;
	SIM_U32(fenykl_slot_gui_app_message.address) = fenykl_slot_gui_app_message.expected;
}

static inline int sim_hud_init(void)
{
	sim_setup_widgets();
	return fenykl_hud_init(FENYKL_HUD_INFO_SCREENS);
}

static volatile uint8_t *sim_px(uint32_t buf, const struct fenykl_hud_elem *e, int r, int c)
{
	return (volatile uint8_t *)(buf + (e->y + r) * SIM_PITCH + e->x + c);
}

static void sim_fill(uint32_t buf, const struct fenykl_hud_elem *e, uint8_t v)
{
	for (int r = 0; r < e->h; r++)
		for (int c = 0; c < e->w; c++)
			*sim_px(buf, e, r, c) = v;
}

static char *sim_dec(char *o, int v)
{
	char s[12];
	int n = 0;

	if (v < 0)
		*o++ = '-', v = -v;
	do
		s[n++] = (char)('0' + v % 10);
	while ((v /= 10));
	while (n)
		*o++ = s[--n];
	*o++ = ' ';
	return o;
}

/* Live view with the info display on the LCD, INFO screen basic info. */
static void sim_setup_gui(void)
{
	for (unsigned int b = 0; b < 2; b++) {
		uint32_t v = SIM_VRAM0 + 16 * b;	/* {pdata, plane, w, h, x, y} */

		SIM_U32(v) = b ? SIM_BUF1 : SIM_BUF0;
		SIM_U32(v + 4) = 2;
		SIM_U16(v + 8) = SIM_PITCH;
		SIM_U16(v + 10) = 600;
		SIM_U32(SIM_VRAM_TABLE + 8 + 4 * b) = v;
	}
	SIM_U8(SIM_SUPER) = 0x01;
	SIM_U8(SIM_STATE) = 0x08;
	SIM_U32(FW_GUI_DISP_REQ) = 0xF001;
	SIM_U32(FW_DISP_DEVICE) = 1;
	SIM_U16(FW_PROP_OVERRIDE_VALID) = 0;
	SIM_U32(SIM_PROP_INFO) = (uint32_t)&sim_info;
	sim_info = SIM_INFO_BASIC;
}

/* A screen without the HUD (image only), and one with it (histogram). */
static void sim_set_hidden(void)
{
	sim_info = SIM_INFO_IMAGE;
}

static void sim_set_visible(void)
{
	sim_info = SIM_INFO_CUSTOM1;
}

/* Two layer-1 buffers, the image table, a visible screen, nothing masked; no font. */
static void sim_setup_memory(void)
{
	sim_setup_gui();
	SIM_U32(SIM_IMAGE_TABLE) = (uint32_t)sim_images;
	SIM_U8(SIM_LAYER_BPP + 1) = 8;
	SIM_U8(SIM_DRAW_BUF) = 0;
	SIM_U16(SIM_HIDE_MASK) = 0;
	SIM_U8(SIM_ONE_MODE) = 0;
}

#endif
